(() => {
  const touchMode=new URLSearchParams(location.search).get('touch')==='1';
  document.body.classList.toggle('touch-mode',touchMode);
  if(!document.querySelector('.view-switcher')){
    const switcher=document.createElement('nav');switcher.className='view-switcher global-view-switcher';switcher.setAttribute('aria-label','Режим отображения');
    const webUrl=new URL(location.href);webUrl.searchParams.delete('touch');const touchUrl=new URL(location.href);touchUrl.searchParams.set('touch','1');
    switcher.innerHTML=`<a class="${touchMode?'':'is-active'}" href="${webUrl.pathname}${webUrl.search}">Веб</a><a class="${touchMode?'is-active':''}" href="${touchUrl.pathname}${touchUrl.search}">Тач</a>`;document.body.append(switcher);
    const style=document.createElement('style');style.textContent=`.global-view-switcher{position:fixed;z-index:5000;top:16px;left:16px;display:flex!important;gap:2px;padding:4px;border:1px solid #e2e1e5;border-radius:18px;background:rgba(255,255,255,.96);box-shadow:0 8px 28px rgba(0,0,0,.14);backdrop-filter:blur(12px)}.global-view-switcher a{display:grid;min-width:54px;height:32px;padding:0 12px;place-items:center;border-radius:14px;color:#77767d;font:500 13px/16px "YS Text",Arial,sans-serif;text-decoration:none}.global-view-switcher a.is-active{background:#222125;color:#fff}`;document.head.append(style);
  }
  const button=document.querySelector('.profile'); if(!button)return;
  button.id='profileButton'; button.type='button'; button.setAttribute('aria-haspopup','menu'); button.setAttribute('aria-expanded','false');
  let menu=document.querySelector('#profileMenu');
  if(!menu){menu=document.createElement('div');menu.id='profileMenu';menu.className='profile-menu';menu.role='menu';menu.hidden=true;menu.innerHTML=`<button class="profile-menu__close" type="button" aria-label="Закрыть"><img src="assets/profile-close-24.svg" alt=""></button><div class="profile-menu__lead"><div class="profile-menu__avatar"><img src="assets/profile-avatar-80.svg" alt=""></div><strong>Иван Иванов</strong><span>ООО «Ромашка»</span></div><div class="profile-menu__group"><a href="payments.html" role="menuitem" data-profile-item="payments"><img src="assets/profile-calendar-24.svg" alt=""><span>График платежей</span></a><a href="payment-documents.html" role="menuitem" data-profile-item="documents"><img src="assets/profile-document-24.svg" alt=""><span>Платежные документы</span></a><button type="button" role="menuitem"><img src="assets/profile-people-24.svg" alt=""><span>Управление пользователями</span></button><button type="button" role="menuitem"><img src="assets/profile-bill-24.svg" alt=""><span>Покупатель в счете-фактуре</span></button><button type="button" role="menuitem"><img src="assets/profile-document-24.svg" alt=""><span>Настройки документов</span></button><button type="button" role="menuitem"><img src="assets/profile-route-24.svg" alt=""><span>Ценовое предложение</span></button></div><div class="profile-menu__divider"></div><div class="profile-menu__group"><button type="button" role="menuitem"><img src="assets/profile-settings-24.svg" alt=""><span>Настройки</span></button><button type="button" role="menuitem"><img src="assets/profile-language-24.svg" alt=""><span>Язык<small>Русский</small></span></button><button type="button" role="menuitem"><img src="assets/profile-night-24.svg" alt=""><span>Тёмная тема</span></button><button type="button" role="menuitem"><img src="assets/profile-exit-24.svg" alt=""><span>Выйти</span></button></div>`;document.querySelector('.topbar').after(menu)}
  const active=location.pathname.endsWith('/payment-documents.html')?'documents':location.pathname.endsWith('/payments.html')?'payments':document.body.dataset.profileSection; menu.querySelectorAll('[data-profile-item]').forEach(item=>item.classList.toggle('is-active',item.dataset.profileItem===active));
  const close=()=>{menu.hidden=true;button.setAttribute('aria-expanded','false')};
  button.addEventListener('click',e=>{e.stopPropagation();const open=menu.hidden;menu.hidden=!open;button.setAttribute('aria-expanded',String(open))});menu.querySelector('.profile-menu__close').addEventListener('click',close);menu.addEventListener('click',e=>e.stopPropagation());document.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
})();
